import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int H = Integer.parseInt(st.nextToken());
        int W = Integer.parseInt(st.nextToken());

        List<int[]> buildings = new ArrayList<>();
        for (int i = 0; i < H; i++) {
            String line = br.readLine();
            for (int j = 0; j < W; j++) {
                if (line.charAt(j) == 'B') {
                    buildings.add(new int[]{i, j});
                }
            }
        }

        int maxDist = 0;
        int n = buildings.size();
        for (int i = 0; i < n; i++) {
            int x1 = buildings.get(i)[0];
            int y1 = buildings.get(i)[1];
            for (int j = i + 1; j < n; j++) {
                int x2 = buildings.get(j)[0];
                int y2 = buildings.get(j)[1];
                int dist = Math.abs(x1 - x2) + Math.abs(y1 - y2);
                if (dist > maxDist) maxDist = dist;
            }
        }

        System.out.println(maxDist);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int H = fs.nextInt();
        int W = fs.nextInt();

        int maxPlus = Integer.MIN_VALUE;
        int minPlus = Integer.MAX_VALUE;
        int maxMinus = Integer.MIN_VALUE;
        int minMinus = Integer.MAX_VALUE;

        for (int i = 0; i < H; i++) {
            String s = fs.next();
            for (int j = 0; j < W; j++) {
                if (s.charAt(j) == 'B') {
                    int plus = i + j;
                    int minus = i - j;
                    if (plus > maxPlus) maxPlus = plus;
                    if (plus < minPlus) minPlus = plus;
                    if (minus > maxMinus) maxMinus = minus;
                    if (minus < minMinus) minMinus = minus;
                }
            }
        }

        int ans = Math.max(maxPlus - minPlus, maxMinus - minMinus);
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

