#define MAX(a,b) ((a) > (b) ? (a) : (b))
#define MIN(a,b) ((a) < (b) ? (a) : (b))

int main() {
    int H, W;
    scanf("%d %d", &H, &W);
    char grid[H][W+1];
    for (int i = 0; i < H; i++) {
        scanf("%s", grid[i]);
    }

    // For Manhattan distance max, we consider four transformations:
    // (i+j), (i-j), (-i+j), (-i-j)
    // Actually we only need two: (i+j) and (i-j)
    // Maximum Manhattan distance = max over all pairs of max of these four combos
    // But simpler: find min and max of (i+j) and (i-j) among buildings

    int min_plus = INT_MAX, max_plus = INT_MIN;
    int min_minus = INT_MAX, max_minus = INT_MIN;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == 'B') {
                int plus = i + j;
                int minus = i - j;
                if (plus < min_plus) min_plus = plus;
                if (plus > max_plus) max_plus = plus;
                if (minus < min_minus) min_minus = minus;
                if (minus > max_minus) max_minus = minus;
            }
        }
    }

    int ans = MAX(max_plus - min_plus, max_minus - min_minus);
    printf("%d\n", ans);

    return 0;
}

